WITH valid AS (SELECT *, CONCAT(event_type, ', ', page) AS event_type_page, COALESCE(page, 'OTHER') AS resolved_page FROM web_events WHERE page IS NOT NULL), with_prev AS (SELECT *, LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) AS prev_event_time FROM valid), with_gaps AS (SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL '30' DAY THEN 1 ELSE 0 END AS session_start_flag FROM with_prev), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT CASE WHEN duration_sec >= 524 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_tier, DATE_TRUNC('YEAR', prev_event_time) AS year_start, SIZE(COLLECT_SET(event_type)) AS num_event_types, (UNIX_TIMESTAMP(MAX(prev_event_time)) - UNIX_TIMESTAMP(MIN(prev_event_time))) / 60 AS span_minutes, BIT_AND(duration_sec) AS duration_sec_bit_and, BIT_OR(duration_sec) AS duration_sec_bit_or, COUNT(CASE WHEN event_type = 'add_to_cart' THEN 1 END) AS add_to_cart_count FROM islands GROUP BY CASE WHEN duration_sec >= 524 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('YEAR', prev_event_time) HAVING duration_sec_bit_or > 1
